// Pseudo-skeleton: handle_stack_fault in a toy OS
void handle_stack_fault(Thread *t, void *fault_addr) {
  if (!in_stack_range(t, fault_addr)) return; // not stack fault
  acquire(&t->stack_lock);
  if (t->stack_limit - t->stack_base < GROW_SIZE) {
    release(&t->stack_lock);
    // terminate or signal OOM
    return;
  }
  map_pages(t, t->stack_limit - GROW_SIZE, GROW_SIZE); // grow downward
  t->stack_limit -= GROW_SIZE;
  release(&t->stack_lock);
  resume_execution(t);
}
```

